func ValidClaim(claim string) bool {
	if len(claim) < 16 || len(claim) > 256 {
		return false
	}
	for _, letter := range claim {
		switch {
		case letter >= 'a' && letter <= 'z', letter >= 'A' && letter <= 'Z', letter >= '0' && letter <= '9', letter == '-', letter == '_':
		default:
			return false
		}
	}
	return true
}

